def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def objective(params):
        return func(clip(params))

    mean = np.zeros(dim)
    sigma = 5.0 * (ub - lb) / np.sqrt(np.log(budget))
    cov = np.eye(dim) * sigma**2

    for _ in range(budget):
        x = rng.multivariate_normal(mean, cov)
        y = objective(x)

        # Update covariance matrix
        mean = mean + 1/np.sqrt(budget) * (x - mean)
        cov = (1-1/budget)*cov + 1/np.sqrt(budget)*(x-mean)@(x-mean).T

    return clip(mean)

def algorithm(func, dim, lb, ub, budget, rng):
    best_x = np.random.uniform(lb, ub, size=dim)
    best_f = func(best_x)

    for _ in range(budget):
        x = np.clip(rng.normal(loc=np.zeros(dim), scale=1.0, size=dim), a_min=lb, a_max=ub)
        f = func(x)

        if f < best_f:
            best_f = f
            best_x = x

    return best_x
